using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Windows.Forms;
namespace LoopFive {
 public class KeyCaptureDialog:Form {
  public Keys Captured;Label prompt=new Label();
  public KeyCaptureDialog(string action){Theme.Style(this);Text="Asignar tecla";ClientSize=new Size(590,220);FormBorderStyle=FormBorderStyle.FixedDialog;StartPosition=FormStartPosition.CenterParent;MaximizeBox=MinimizeBox=false;KeyPreview=true;Label title=new Label{Text=action,Font=Theme.Medium,ForeColor=Theme.Text,Location=new Point(20,20),Size=new Size(550,48)};Controls.Add(title);prompt.Text="Pulsa una tecla o una combinación con Ctrl, Shift o Alt.";prompt.ForeColor=Theme.Green;prompt.SetBounds(20,80,550,60);Controls.Add(prompt);Label hint=Theme.Label("Esc y Espacio también se pueden asignar. Usa el botón para cancelar.");hint.Location=new Point(20,145);Controls.Add(hint);Button cancel=Theme.Button("Cancelar",delegate{DialogResult=DialogResult.Cancel;Close();});cancel.SetBounds(435,176,130,30);Controls.Add(cancel);}
  protected override bool ProcessCmdKey(ref Message msg,Keys keyData){Keys code=keyData&Keys.KeyCode;if(code==Keys.ShiftKey||code==Keys.ControlKey||code==Keys.Menu){prompt.Text="Mantén el modificador y pulsa la tecla elegida…";return true;}string error=KeyboardCatalog.InvalidKey(keyData);if(error!=null){prompt.Text=error;return true;}Captured=keyData;DialogResult=DialogResult.OK;Close();return true;}
 }
 public class KeyboardPage:UserControl {
  Engine engine;Action release;ComboBox group;TextBox search;DataGridView grid;CheckBox enabled;Label summary;bool syncing;
  public KeyboardPage(Engine e,Action releaseHeld){engine=e;release=releaseHeld;KeyDefaults.Ensure(e.System);Dock=DockStyle.Fill;Theme.Style(this);
   TableLayoutPanel layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=4,ColumnCount=1,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,80));Controls.Add(layout);
   Label intro=new Label{Dock=DockStyle.Fill,Text="CONFIGURA TU TECLADO\r\nSelecciona una función y pulsa Asignar tecla. El botón circular de cada pista es REC / PLAY / OVERDUB.",ForeColor=Theme.Text,Font=Theme.Small};layout.Controls.Add(intro,0,0);
   FlowLayoutPanel filters=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};group=Theme.Combo(new string[]{"Todas","Pista 1","Pista 2","Pista 3","Pista 4","Pista 5","Pista seleccionada","Global","Input FX","Track FX","Ritmo","Programa / memorias"});group.Width=170;filters.Controls.Add(group);search=new TextBox{Width=230,BackColor=Theme.Panel,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(10,4,10,0)};filters.Controls.Add(Theme.Label("Buscar"));filters.Controls.Add(search);enabled=Theme.Check("Atajos activados");enabled.Checked=engine.System.KeyboardEnabled;filters.Controls.Add(enabled);summary=Theme.Label("");filters.Controls.Add(summary);layout.Controls.Add(filters,0,1);
   grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,RowHeadersVisible=false,BackgroundColor=Theme.Background,GridColor=Theme.Line,BorderStyle=BorderStyle.None,EnableHeadersVisualStyles=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};grid.DefaultCellStyle.BackColor=Theme.Panel;grid.DefaultCellStyle.ForeColor=Theme.Text;grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(42,77,70);grid.ColumnHeadersDefaultCellStyle.BackColor=Theme.Background;grid.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Muted;grid.RowTemplate.Height=30;grid.Columns.Add("Group","Grupo");grid.Columns[0].FillWeight=25;grid.Columns.Add("Action","Función");grid.Columns[1].FillWeight=75;grid.Columns.Add("Key","Tecla / combinación");grid.Columns[2].FillWeight=30;grid.CellFormatting+=delegate(object sender,DataGridViewCellFormattingEventArgs args){if(args.Value is string)args.Value=Language.T((string)args.Value);};grid.CellDoubleClick+=delegate(object s,DataGridViewCellEventArgs args){if(args.RowIndex>=0)AssignSelected();};layout.Controls.Add(grid,0,2);
   FlowLayoutPanel buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};Add(buttons,"ASIGNAR TECLA",150,AssignSelected);Add(buttons,"Quitar tecla",110,ClearSelected);Add(buttons,"Restablecer",110,Reset);Add(buttons,"Exportar perfil",125,ExportProfile);Add(buttons,"Importar perfil",125,ImportProfile);Label note=Theme.Label("Cambios guardados al instante. Atajos activos sólo con la app enfocada; se suspenden aquí, al escribir y en diálogos. Una pulsación ejecuta una vez; mantener un FX funciona hasta soltar.");note.MaximumSize=new Size(1080,0);buttons.Controls.Add(note);layout.Controls.Add(buttons,0,3);
   group.SelectedIndexChanged+=delegate{Reload();};search.TextChanged+=delegate{Reload();};enabled.CheckedChanged+=delegate{if(!syncing)Commit(CloneBindings(),enabled.Checked);};Reload();}
  void Add(FlowLayoutPanel p,string text,int w,Action action){Button b=Theme.Button(text,action);b.Width=w;p.Controls.Add(b);}
  List<KeyBinding> CloneBindings(){return Storage.Clone(engine.System.KeyboardBindings);}
  string SelectedId(){return grid.CurrentRow==null?null:Convert.ToString(grid.CurrentRow.Tag);}
  public void Reload(){string id=SelectedId();grid.Rows.Clear();string text=search.Text.Trim();foreach(KeyboardCommand action in KeyboardCatalog.Commands){if(group.SelectedIndex>0&&action.Group!=group.SelectedItem.ToString())continue;if(text.Length>0&&action.Name.IndexOf(text,StringComparison.CurrentCultureIgnoreCase)<0&&action.Group.IndexOf(text,StringComparison.CurrentCultureIgnoreCase)<0&&Language.T(action.Name).IndexOf(text,StringComparison.CurrentCultureIgnoreCase)<0)continue;KeyBinding binding=engine.System.KeyboardBindings.Find(delegate(KeyBinding b){return b!=null&&b.Action==action.Id;});int row=grid.Rows.Add(action.Group,action.Name,KeyboardCatalog.KeyName(binding==null?0:binding.Key));grid.Rows[row].Tag=action.Id;if(action.Id==id)grid.CurrentCell=grid.Rows[row].Cells[1];}summary.Text=engine.System.KeyboardBindings.Count+" teclas · "+KeyboardCatalog.Commands.Count+" funciones";syncing=true;enabled.Checked=engine.System.KeyboardEnabled;syncing=false;}
  public void Commit(List<KeyBinding> bindings,bool on){KeyboardCatalog.Validate(bindings);release();List<KeyBinding> old=engine.System.KeyboardBindings;bool wasOn=engine.System.KeyboardEnabled;engine.System.KeyboardBindings=bindings;engine.System.KeyboardEnabled=on;try{Storage.SaveSystem(engine.System);}catch{engine.System.KeyboardBindings=old;engine.System.KeyboardEnabled=wasOn;throw;}Reload();}
  public string Conflict(string id,Keys key){KeyBinding other=engine.System.KeyboardBindings.Find(delegate(KeyBinding b){return b!=null&&b.Action!=id&&b.Key==(int)key;});return other==null?null:other.Action;}
  public void Assign(string id,Keys key,bool replaceConflict){if(KeyboardCatalog.Find(id)==null)throw new Exception("Selecciona una función válida.");string error=KeyboardCatalog.InvalidKey(key);if(error!=null)throw new Exception(error);string conflict=Conflict(id,key);if(conflict!=null&&!replaceConflict)throw new Exception("La tecla ya está asignada a "+KeyboardCatalog.Find(conflict).Name);List<KeyBinding> copy=CloneBindings();copy.RemoveAll(delegate(KeyBinding b){return b.Action==id||b.Key==(int)key;});copy.Add(new KeyBinding{Action=id,Key=(int)key});Commit(copy,engine.System.KeyboardEnabled);}
  void AssignSelected(){string id=SelectedId();if(id==null)return;using(KeyCaptureDialog capture=new KeyCaptureDialog(KeyboardCatalog.Find(id).Name))if(capture.ShowDialog(FindForm())==DialogResult.OK){string conflict=Conflict(id,capture.Captured);if(conflict!=null&&UiMessage.Show(KeyboardCatalog.KeyName((int)capture.Captured)+" ya controla:\n"+KeyboardCatalog.Find(conflict).Name+"\n\n¿Mover esa tecla a la función seleccionada?","Tecla ya asignada",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;Assign(id,capture.Captured,true);}}
  void ClearSelected(){string id=SelectedId();if(id==null)return;List<KeyBinding> copy=CloneBindings();copy.RemoveAll(delegate(KeyBinding b){return b.Action==id;});Commit(copy,engine.System.KeyboardEnabled);}
  void Reset(){if(UiMessage.Show("¿Restaurar las teclas predeterminadas? Puedes exportar tu perfil antes.","Restablecer teclado",MessageBoxButtons.YesNo)==DialogResult.Yes)Commit(KeyDefaults.Create(),true);}
  public void WriteProfile(string path){KeyboardProfile profile=new KeyboardProfile{Bindings=CloneBindings()};Storage.Atomic(path,delegate(Stream s){byte[] json=Storage.Json(profile);s.Write(json,0,json.Length);});}
  public void ReadProfile(string path){KeyboardProfile profile=Storage.FromJson<KeyboardProfile>(File.ReadAllBytes(path));if(profile==null||profile.Version!=1)throw new Exception("Perfil de teclado no compatible.");KeyboardCatalog.Validate(profile.Bindings);Commit(profile.Bindings,engine.System.KeyboardEnabled);}
  void ExportProfile(){using(SaveFileDialog d=new SaveFileDialog{Filter=Language.Filter("Perfil de teclado LoopFive|*.loopkeys"),FileName="Mi-teclado.loopkeys"})if(d.ShowDialog(FindForm())==DialogResult.OK)WriteProfile(d.FileName);}
  void ImportProfile(){using(OpenFileDialog d=new OpenFileDialog{Filter=Language.Filter("Perfil de teclado LoopFive|*.loopkeys")})if(d.ShowDialog(FindForm())==DialogResult.OK){if(UiMessage.Show("¿Reemplazar las asignaciones actuales por las de este perfil?","Importar teclado",MessageBoxButtons.YesNo)==DialogResult.Yes)ReadProfile(d.FileName);}}
  public void FocusSearch(){search.Focus();}
 }
 public class KeyboardMessageFilter:IMessageFilter {
  MainForm form;Func<bool> active;Func<Keys> modifiers;public KeyboardMessageFilter(MainForm f):this(f,delegate{return Form.ActiveForm==f;},delegate{return Control.ModifierKeys;}){}public KeyboardMessageFilter(MainForm f,Func<bool> isActive,Func<Keys> currentModifiers){form=f;active=isActive;modifiers=currentModifiers;}
  public bool PreFilterMessage(ref Message msg){int wm=msg.Msg;if(wm!=0x100&&wm!=0x101&&wm!=0x104&&wm!=0x105)return false;Keys code=(Keys)(msg.WParam.ToInt64()&65535);if(wm==0x101||wm==0x105)return form.Keyboard.Up(code);if(!active()||!form.KeyboardAllowed)return false;Control focus=Control.FromHandle(msg.HWnd);for(Control c=focus;c!=null&&c!=form;c=c.Parent)if(c is TextBoxBase||c is NumericUpDown||c is ComboBox||c is DataGridView||c is KeyboardPage)return false;try{bool handled=form.Keyboard.Down(code|modifiers());if(handled)form.KeyboardActionCompleted();return handled;}catch(Exception e){UiMessage.Show(e.Message,"Teclado LoopFive");return true;}}
 }
}
